import{_ as t,o as n,a as p,c as a,d as l,b as c}from"./app.C41L12d5.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/getting_started.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/getting_started.md","outlineHeaders":[{"level":2,"title":"算子概述","slug":"算子概述","link":"#算子概述"},{"level":2,"title":"算子实现","slug":"算子实现","link":"#算子实现"},{"level":2,"title":"实现流程解析","slug":"实现流程解析","link":"#实现流程解析"},{"level":2,"title":"可优化方向分析","slug":"可优化方向分析","link":"#可优化方向分析"},{"level":2,"title":"功能调试","slug":"功能调试","link":"#功能调试"},{"level":3,"title":"printf","slug":"printf","link":"#printf"},{"level":3,"title":"DumpTensor","slug":"DumpTensor","link":"#DumpTensor"},{"level":2,"title":"性能调试","slug":"性能调试","link":"#性能调试"},{"level":3,"title":"msOpProf工具介绍","slug":"msOpProf工具介绍","link":"#msOpProf工具介绍"}],"lastUpdated":1787050286000}'),e={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/getting_started.md"},o={class:"markdown-body"},d={tabindex:"0",class:"MathJax",jax:"SVG",display:"true",style:{direction:"ltr",display:"block","text-align":"center",margin:"1em 0",position:"relative"}},r={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.464ex"},xmlns:"http://www.w3.org/2000/svg",width:"11.457ex",height:"1.783ex",role:"img",focusable:"false",viewBox:"0 -583 5063.9 788","aria-hidden":"true"};function i(h,s,T,g,m,Q){return n(),p("div",null,[a("div",null,[a("article",o,[s[1]||(s[1]=a("h1",null,[l("入门功能落地"),a("span",{id:"ZH-CN_TOPIC_000000_ADD_ENTRY"})],-1)),s[2]||(s[2]=a("p",null,"本节以Add（向量加法）算子为例，介绍基于Ascend C编程模型实现向量算子的基本方法，帮助开发者快速入门SIMD算子开发。",-1)),s[3]||(s[3]=a("h2",{id:"算子概述"},[l("算子概述"),a("a",{class:"header-anchor",href:"#算子概述"},"​")],-1)),s[4]||(s[4]=a("p",null,"Add算子实现两个向量的逐元素加法运算，计算公式为：",-1)),a("p",null,[a("mjx-container",d,[(n(),p("svg",r,[...s[0]||(s[0]=[c('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="msub"><g data-mml-node="mi"><path data-c="1D467" d="M347 338Q337 338 294 349T231 360Q211 360 197 356T174 346T162 335T155 324L153 320Q150 317 138 317Q117 317 117 325Q117 330 120 339Q133 378 163 406T229 440Q241 442 246 442Q271 442 291 425T329 392T367 375Q389 375 411 408T434 441Q435 442 449 442H462Q468 436 468 434Q468 430 463 420T449 399T432 377T418 358L411 349Q368 298 275 214T160 106L148 94L163 93Q185 93 227 82T290 71Q328 71 360 90T402 140Q406 149 409 151T424 153Q443 153 443 143Q443 138 442 134Q425 72 376 31T278 -11Q252 -11 232 6T193 40T155 57Q111 57 76 -3Q70 -11 59 -11H54H41Q35 -5 35 -2Q35 13 93 84Q132 129 225 214T340 322Q352 338 347 338Z" style="stroke-width:3;"></path></g><g data-mml-node="mi" transform="translate(498,-150) scale(0.707)"><path data-c="1D456" d="M184 600Q184 624 203 642T247 661Q265 661 277 649T290 619Q290 596 270 577T226 557Q211 557 198 567T184 600ZM21 287Q21 295 30 318T54 369T98 420T158 442Q197 442 223 419T250 357Q250 340 236 301T196 196T154 83Q149 61 149 51Q149 26 166 26Q175 26 185 29T208 43T235 78T260 137Q263 149 265 151T282 153Q302 153 302 143Q302 135 293 112T268 61T223 11T161 -11Q129 -11 102 10T74 74Q74 91 79 106T122 220Q160 321 166 341T173 380Q173 404 156 404H154Q124 404 99 371T61 287Q60 286 59 284T58 281T56 279T53 278T49 278T41 278H27Q21 284 21 287Z" style="stroke-width:3;"></path></g></g><g data-mml-node="mo" transform="translate(1069.7,0)"><path data-c="3D" d="M56 347Q56 360 70 367H707Q722 359 722 347Q722 336 708 328L390 327H72Q56 332 56 347ZM56 153Q56 168 72 173H708Q722 163 722 153Q722 140 707 133H70Q56 140 56 153Z" style="stroke-width:3;"></path></g><g data-mml-node="msub" transform="translate(2125.5,0)"><g data-mml-node="mi"><path data-c="1D465" d="M52 289Q59 331 106 386T222 442Q257 442 286 424T329 379Q371 442 430 442Q467 442 494 420T522 361Q522 332 508 314T481 292T458 288Q439 288 427 299T415 328Q415 374 465 391Q454 404 425 404Q412 404 406 402Q368 386 350 336Q290 115 290 78Q290 50 306 38T341 26Q378 26 414 59T463 140Q466 150 469 151T485 153H489Q504 153 504 145Q504 144 502 134Q486 77 440 33T333 -11Q263 -11 227 52Q186 -10 133 -10H127Q78 -10 57 16T35 71Q35 103 54 123T99 143Q142 143 142 101Q142 81 130 66T107 46T94 41L91 40Q91 39 97 36T113 29T132 26Q168 26 194 71Q203 87 217 139T245 247T261 313Q266 340 266 352Q266 380 251 392T217 404Q177 404 142 372T93 290Q91 281 88 280T72 278H58Q52 284 52 289Z" style="stroke-width:3;"></path></g><g data-mml-node="mi" transform="translate(605,-150) scale(0.707)"><path data-c="1D456" d="M184 600Q184 624 203 642T247 661Q265 661 277 649T290 619Q290 596 270 577T226 557Q211 557 198 567T184 600ZM21 287Q21 295 30 318T54 369T98 420T158 442Q197 442 223 419T250 357Q250 340 236 301T196 196T154 83Q149 61 149 51Q149 26 166 26Q175 26 185 29T208 43T235 78T260 137Q263 149 265 151T282 153Q302 153 302 143Q302 135 293 112T268 61T223 11T161 -11Q129 -11 102 10T74 74Q74 91 79 106T122 220Q160 321 166 341T173 380Q173 404 156 404H154Q124 404 99 371T61 287Q60 286 59 284T58 281T56 279T53 278T49 278T41 278H27Q21 284 21 287Z" style="stroke-width:3;"></path></g></g><g data-mml-node="mo" transform="translate(3246.7,0)"><path data-c="2B" d="M56 237T56 250T70 270H369V420L370 570Q380 583 389 583Q402 583 409 568V270H707Q722 262 722 250T707 230H409V-68Q401 -82 391 -82H389H387Q375 -82 369 -68V230H70Q56 237 56 250Z" style="stroke-width:3;"></path></g><g data-mml-node="msub" transform="translate(4246.9,0)"><g data-mml-node="mi"><path data-c="1D466" d="M21 287Q21 301 36 335T84 406T158 442Q199 442 224 419T250 355Q248 336 247 334Q247 331 231 288T198 191T182 105Q182 62 196 45T238 27Q261 27 281 38T312 61T339 94Q339 95 344 114T358 173T377 247Q415 397 419 404Q432 431 462 431Q475 431 483 424T494 412T496 403Q496 390 447 193T391 -23Q363 -106 294 -155T156 -205Q111 -205 77 -183T43 -117Q43 -95 50 -80T69 -58T89 -48T106 -45Q150 -45 150 -87Q150 -107 138 -122T115 -142T102 -147L99 -148Q101 -153 118 -160T152 -167H160Q177 -167 186 -165Q219 -156 247 -127T290 -65T313 -9T321 21L315 17Q309 13 296 6T270 -6Q250 -11 231 -11Q185 -11 150 11T104 82Q103 89 103 113Q103 170 138 262T173 379Q173 380 173 381Q173 390 173 393T169 400T158 404H154Q131 404 112 385T82 344T65 302T57 280Q55 278 41 278H27Q21 284 21 287Z" style="stroke-width:3;"></path></g><g data-mml-node="mi" transform="translate(523,-150) scale(0.707)"><path data-c="1D456" d="M184 600Q184 624 203 642T247 661Q265 661 277 649T290 619Q290 596 270 577T226 557Q211 557 198 567T184 600ZM21 287Q21 295 30 318T54 369T98 420T158 442Q197 442 223 419T250 357Q250 340 236 301T196 196T154 83Q149 61 149 51Q149 26 166 26Q175 26 185 29T208 43T235 78T260 137Q263 149 265 151T282 153Q302 153 302 143Q302 135 293 112T268 61T223 11T161 -11Q129 -11 102 10T74 74Q74 91 79 106T122 220Q160 321 166 341T173 380Q173 404 156 404H154Q124 404 99 371T61 287Q60 286 59 284T58 281T56 279T53 278T49 278T41 278H27Q21 284 21 287Z" style="stroke-width:3;"></path></g></g></g></g>',1)])]))])]),s[5]||(s[5]=c(`<ul><li>x：输入，shape为[8, 2048]，数据类型为float；</li><li>y：输入，shape为[8, 2048]，数据类型为float；</li><li>z：输出，shape为[8, 2048]，数据类型为float；</li></ul><p>样例运行参数：使用8个核完成计算，每个核处理2048个float元素（<code>blockLength = 2048</code>），数据总量为16384个float元素。</p><h2 id="算子实现">算子实现<a class="header-anchor" href="#算子实现">​</a></h2><p>Add算子的计算逻辑遵循&quot;搬入-计算-搬出&quot;三段式流水结构：</p><ol><li>将输入数据x和y从<a href="../../../../../api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor_intro.html">GM</a>（Global Memory，芯片外部全局内存）搬运到<a href="../../../../../api/SIMD-API/basic_api/data_structures/LocalTensor/LocalTensor_intro.html">Unified Buffer（UB）</a>（向量计算专用片上缓存）；</li><li>在UB上对xLocal、yLocal执行向量加法操作，计算结果存储在zLocal中；</li><li>将计算结果从UB搬运回GM。</li></ol><p><strong>前置说明</strong>：</p><ul><li><a href="../../../../../api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor_intro.html">GM（Global Memory）</a>：AI Core外部的全局存储，数据通过<a href="../../../../../api/SIMD-API/basic_api/data_structures/GlobalTensor/GlobalTensor_intro.html">GlobalTensor</a>访问，容量大但访问速度较慢。</li><li><a href="../../../../../api/SIMD-API/basic_api/data_structures/LocalTensor/LocalTensor_intro.html">UB</a>：AI Core内部的向量计算专用缓存，数据通过<a href="../../../../../api/SIMD-API/basic_api/data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>访问，容量有限但访问速度快。</li><li><a href="../../../../../api/SIMD-API/basic_api/memory_vector_compute/data_move/DataCopy_GMAndUB_continuous.html">DataCopy</a>：用于在GM和UB之间搬运数据的API。</li><li><a href="../../../../../api/SIMD-API/basic_api/sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier</a>：流水线同步屏障，确保数据搬运完成后再执行后续操作。</li><li><code>block_idx</code>：通过<a href="../../../../../api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetBlockIdx.html">GetBlockIdx()</a>获取当前核编号，用于多核并行时的数据分片。</li></ul><p>核心代码如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span>
<span class="n">__vector__</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">InitSocState</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// Global Tensor：在GM上分配输入/输出缓冲区，按block_idx偏移实现分核</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">zGm</span><span class="p">;</span>
<span class="w">    </span><span class="n">xGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockLength</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">yGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockLength</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">zGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">z</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockLength</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// Local Tensor：在UB上分配计算缓冲区</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">UB</span><span class="o">&gt;</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">xLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">yLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">zLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// GM -&gt; UB: 搬入输入数据</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// 向量计算: z = x + y</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// UB -&gt; GM: 搬出计算结果</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">zGm</span><span class="p">,</span><span class="w"> </span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><h2 id="实现流程解析">实现流程解析<a class="header-anchor" href="#实现流程解析">​</a></h2><table><thead><tr><th align="center">阶段</th><th align="left">数据流动/行为</th><th align="left">实现目的/原因</th></tr></thead><tbody><tr><td align="center">初始化</td><td align="left"><code>InitSocState()</code></td><td align="left">初始化AI Core硬件状态</td></tr><tr><td align="center">GM地址分配</td><td align="left"><code>SetGlobalBuffer(x + block_idx * blockLength)</code></td><td align="left">每个核按<code>block_idx</code>偏移处理各自数据段，实现多核并行</td></tr><tr><td align="center">UB空间分配</td><td align="left"><code>ubAllocator.Alloc&lt;float, blockLength&gt;()</code></td><td align="left">在UB上为x、y、z分配计算缓冲区</td></tr><tr><td align="center">搬入（Stage 1）</td><td align="left">GM → UB：<code>DataCopy(xLocal, xGm)</code>、<code>DataCopy(yLocal, yGm)</code></td><td align="left">将输入数据从GM搬到UB，因为向量计算单元只能访问UB数据</td></tr><tr><td align="center">流水同步</td><td align="left"><code>PipeBarrier&lt;PIPE_ALL&gt;()</code></td><td align="left">确保搬入完成后再计算，避免读未就绪数据</td></tr><tr><td align="center">计算（Stage 2）</td><td align="left">UB上计算：<code>Add(zLocal, xLocal, yLocal)</code></td><td align="left">在UB上执行向量加法，利用向量单元并行处理多元素</td></tr><tr><td align="center">流水同步</td><td align="left"><code>PipeBarrier&lt;PIPE_ALL&gt;()</code></td><td align="left">确保计算完成后再搬出</td></tr><tr><td align="center">搬出（Stage 3）</td><td align="left">UB → GM：<code>DataCopy(zGm, zLocal)</code></td><td align="left">将结果从UB搬回GM供后续使用</td></tr><tr><td align="center">流水同步</td><td align="left"><code>PipeBarrier&lt;PIPE_ALL&gt;()</code></td><td align="left">确保搬出完成，保证数据一致性</td></tr></tbody></table><h2 id="可优化方向分析">可优化方向分析<a class="header-anchor" href="#可优化方向分析">​</a></h2><table><thead><tr><th>序号</th><th>可优化方向</th><th>当前实现的问题</th><th>预期优化收益</th></tr></thead><tbody><tr><td>1</td><td>多核动态分配</td><td>固定使用8个核，未根据实际可用核数动态分配</td><td>动态获取可用核数，充分利用多核并行能力，减少端到端耗时</td></tr><tr><td>2</td><td>增大搬运粒度</td><td>每次搬运2048个float元素（8KB），搬运粒度较小</td><td>增大单次搬运数据量，减少搬运次数，摊薄启动开销，提升带宽利用率</td></tr><tr><td>3</td><td>双缓冲流水线并行</td><td>搬入、计算、搬出三个阶段严格串行执行，各硬件单元（MTE2/V/MTE3）无法同时工作</td><td>采用Ping-Pong双缓冲机制，使搬入、计算、搬出可并行执行，隐藏搬运延迟</td></tr><tr><td>4</td><td>L2 Cache bypass</td><td>Add输入数据只读取一次，但默认经过L2 Cache，增加了Cache污染</td><td>对流式访问数据设置L2 Cache bypass，减少不必要的Cache开销，提升搬运效率</td></tr></tbody></table><p>完整样例代码请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/00_introduction/01_add/add">Add入门样例</a>。</p><h2 id="功能调试">功能调试<a class="header-anchor" href="#功能调试">​</a></h2><h3 id="printf">printf<a class="header-anchor" href="#printf">​</a></h3><p>该接口提供CPU域/NPU域调试场景下的格式化输出功能。</p><p>在算子kernel侧实现代码中需要输出日志信息的地方调用<a href="../../../../../api/Utils-API/tuning_interface/printf.html">printf</a>接口打印相关内容。</p><p>示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">printf</span><span class="p">(</span><span class="s">&quot;add blockIdx=%d</span><span class="se">\\n</span><span class="s">&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockIdx</span><span class="p">());</span>
</code></pre></div><blockquote><p><strong>注意：</strong> printf（PRINTF）接口打印功能会对算子实际运行的性能带来一定影响，通常在调测阶段使用。开发者可以按需通过设置<code>ASCENDC_DUMP=0</code>的方式关闭打印功能。</p></blockquote><h3 id="DumpTensor">DumpTensor<a class="header-anchor" href="#DumpTensor">​</a></h3><p>基于算子工程开发的算子，可以使用该接口Dump指定<a href="../../../../../api/SIMD-API/basic_api/data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>的内容。同时支持打印自定义的附加信息（仅支持uint32_t数据类型的信息），比如打印当前行号等。</p><p>在算子kernel侧实现代码中需要打印Tensor数据的地方调用<a href="../../../../../api/SIMD-API/basic_api/debug_interface/onboard_print/DumpTensor.html">DumpTensor</a>接口打印相关内容。样例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 向量计算: z = x + y</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">DumpTensor</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">);</span>
</code></pre></div><blockquote><p><strong>注意：</strong> DumpTensor接口打印功能会对算子实际运行的性能带来一定影响，通常在调测阶段使用。开发者可以按需通过设置<code>ASCENDC_DUMP=0</code>来关闭打印功能。</p></blockquote><h2 id="性能调试">性能调试<a class="header-anchor" href="#性能调试">​</a></h2><h3 id="msOpProf工具介绍">msOpProf工具介绍<a class="header-anchor" href="#msOpProf工具介绍">​</a></h3><p>msOpProf工具是单算子性能分析工具。包含msopprof和msopprof simulator两种使用方式。该工具协助用户定位算子内存、算子代码以及算子指令的异常，实现全方位的算子调优。当前支持基于不同运行模式（上板或仿真）和不同文件形式（可执行文件或算子二进制.o文件）进行性能数据的采集和自动解析。</p><ul><li><p>上板性能采集</p><p>通过上板性能采集，可以直接测定算子昇腾AI处理器上的运行时间。该方式适合在板环境中快速定位算子性能问题。</p><p>基于可执行文件demo通过msopprof执行算子调优：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>msopprof ./demo
</code></pre></div><ul><li><p>性能数据说明<br> 命令完成后，会在默认目录下生成以“OPPROF_{timestamp}_XXX”命名的文件夹,性能数据文件夹结构示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>├──dump<span class="w">                       </span><span class="c1"># 原始的性能数据，用户无需关注</span>
├──ArithmeticUtilization.csv<span class="w">  </span><span class="c1"># cube/vector指令cycle占比</span>
├──L2Cache.csv<span class="w">                </span><span class="c1"># L2 Cache命中率，影响MTE2，建议合理规划数据搬运逻辑，增加命中率</span>
├──Memory.csv<span class="w">                 </span><span class="c1"># UB，L1和主存储器读写带宽速率</span>
├──MemoryL0.csv<span class="w">               </span><span class="c1"># L0A，L0B，和L0C读写带宽速率</span>
├──MemoryUB.csv<span class="w">               </span><span class="c1"># Vector和Scalar到UB的读写带宽速率</span>
├──OpBasicInfo.csv<span class="w">            </span><span class="c1"># 算子基础信息</span>
├──PipeUtilization.csv<span class="w">        </span><span class="c1"># 采集计算单元和搬运单元耗时和占比</span>
├──ResourceConflictRatio.csv<span class="w">  </span><span class="c1"># UB上的bank group、bank conflict和资源冲突率在所有指令中的占比</span>
└──visualize_data.bin<span class="w">         </span><span class="c1"># MindStudio Insight呈现文件</span>
</code></pre></div></li></ul></li></ul><p>查看具体的性能分析结果：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># 查看Task Duration 以及各项数据</span>
cat<span class="w"> </span>./OPPROF_*/PipeUtilization.csv
</code></pre></div><p>请参考 <a href="https://gitcode.com/Ascend/msopprof/blob/master/docs/zh/user_guide/msopprof_user_guide.md">《msOpProf用户指南》</a>算子调优（msOpProf）中的内容。</p><p>完整性能调优过程请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/05_best_practices/00_vector_compute/add_high_performance">Add性能调优样例</a>。</p>`,34))])])])}const b=t(e,[["render",i]]);export{f as __pageData,b as default};
